package com.northstarbank.console.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="financial_requests") public class FinancialRequest{@Id public String id;public String kind;public String customerId;public String originalFeeReference;public BigDecimal amount;public String justification;public String requester;public String approver;public String owningBranch;public String authorizationBasis;public String status;public boolean preAuthorized;public String coreReference;public Instant requestedAt=Instant.now();protected FinancialRequest(){}public FinancialRequest(String id,String kind,String customerId,BigDecimal amount,String why,String requester,String branch,boolean preAuthorized){this.id=id;this.kind=kind;this.customerId=customerId;this.amount=amount;justification=why;this.requester=requester;owningBranch=branch;this.preAuthorized=preAuthorized;status="requested";}}
